//! Arena-allocated HCL / Terraform AST, modelled on `oxc_ast`.
//!
//! - Node definitions: [`ast`] (the single source of truth).
//! - Generated by `tf_ast_codegen`: [`AstKind`], [`AstType`], [`Visit`],
//!   [`VisitMut`], `walk_*` functions and `GetSpan` impls.
//! - Hand-written helpers for downstream consumers: [`ast_impl`].
//! - Comments are not in the tree; they are returned on the side as
//!   [`Comment`]s by the parser.

pub mod ast;
mod ast_impl;
mod comment;
mod generated;

pub use ast::*;
pub use comment::{Comment, CommentKind};
pub use generated::ast_kind::{AstKind, AstType};
pub use generated::visit::{self as visit, Visit};
pub use generated::visit_mut::{self as visit_mut, VisitMut};
pub use tf_span::{GetSpan, Span};

#[cfg(test)]
mod size_tests {
    use super::*;
    use std::mem::size_of;

    /// Spike success criterion: `Expression` is 16 bytes (tag + arena pointer).
    #[test]
    fn expression_is_16_bytes() {
        assert_eq!(size_of::<Expression<'_>>(), 16);
    }

    #[test]
    fn other_enums_are_16_bytes() {
        assert_eq!(size_of::<BodyItem<'_>>(), 16);
        assert_eq!(size_of::<TemplateElement<'_>>(), 16);
        assert_eq!(size_of::<TraversalOperator<'_>>(), 16);
        assert_eq!(size_of::<ObjectKey<'_>>(), 16);
    }

    #[test]
    fn node_sizes() {
        // Not criteria, just guards against accidental growth.
        assert_eq!(size_of::<Identifier<'_>>(), 24);
        assert_eq!(size_of::<Attribute<'_>>(), 48);
    }
}
